  [inst_3 : Fintype.{0} P] [inst_4 : Fintype.{0} A] [inst_5 : Fintype.{0} D] {cfg : DefiKernel.Composition.Config P A D}
  {boundary : DefiKernel.Composition.Boundary P A D} {index : Nat}
  {history : List.{0} (DefiKernel.Composition.OutputObservation A)} {step : DefiKernel.Composition.Step P A D}
  {pre : DefiKernel.Composition.World P A D} {result : DefiKernel.Composition.StepResult P A D}
  (edges : List.{0} DefiKernel.Interface.Binding),
  @DefiKernel.Interface.Agrees P A D (@DefiKernel.Composition.Config.catalog P A D cfg) edges
      (@DefiKernel.Typed.ExecutionResult.state P A D pre) →
    @Eq.{1} (Except.{0, 0} DefiKernel.Composition.Failure (DefiKernel.Composition.StepResult P A D))
        (@DefiKernel.Composition.executeStep P A D inst inst_1 inst_2 inst_3 inst_4 inst_5 cfg boundary index history
          step pre)
        (@Except.ok.{0, 0} DefiKernel.Composition.Failure (DefiKernel.Composition.StepResult P A D) result) →
      (∀ (edge : DefiKernel.Interface.Binding),
          @Membership.mem.{0, 0} DefiKernel.Interface.Binding (List.{0} DefiKernel.Interface.Binding)
              (@List.instMembership.{0} DefiKernel.Interface.Binding) edges edge →
            ∀ (left right : DefiKernel.Typed.Cell P A D),
              @Eq.{1} (Except.{0, 0} DefiKernel.Interface.EndpointFailure (DefiKernel.Typed.Cell P A D))
                  (@DefiKernel.Interface.resolveExport P A D (@DefiKernel.Composition.Config.catalog P A D cfg)
                    (@Prod.fst.{0, 0} DefiKernel.Composition.QualifiedPort DefiKernel.Composition.QualifiedPort edge))
                  (@Except.ok.{0, 0} DefiKernel.Interface.EndpointFailure (DefiKernel.Typed.Cell P A D) left) →
                @Eq.{1} (Except.{0, 0} DefiKernel.Interface.EndpointFailure (DefiKernel.Typed.Cell P A D))
                    (@DefiKernel.Interface.resolveExport P A D (@DefiKernel.Composition.Config.catalog P A D cfg)
                      (@Prod.snd.{0, 0} DefiKernel.Composition.QualifiedPort DefiKernel.Composition.QualifiedPort edge))
                    (@Except.ok.{0, 0} DefiKernel.Interface.EndpointFailure (DefiKernel.Typed.Cell P A D) right) →
                  And
                    (left ∉
                      @DefiKernel.Composition.Receipt.writes P A D
                        (@DefiKernel.Composition.StepResult.receipt P A D result))
                    (right ∉
                      @DefiKernel.Composition.Receipt.writes P A D
                        (@DefiKernel.Composition.StepResult.receipt P A D result))) →
        @DefiKernel.Interface.Agrees P A D (@DefiKernel.Composition.Config.catalog P A D cfg) edges
          (@DefiKernel.Typed.ExecutionResult.state P A D (@DefiKernel.Composition.StepResult.world P A D result))

