def NeutralOn (region : Region P A D) (cells : Finset (Cell P A D))
    (receipt : Receipt P A D) : Prop :=
  (region.cells ∩ cells).sum (receiptCellEffect receipt) = 0

def TypedTotalContract (region : Region P A D) (value : State P A D → ℚ)
    (state : State P A D) : Prop :=
  region.WellFormed ∧ balanceSum region state = value state

def attemptDeltaSum (region : Region P A D)
    (attempts : List (Interleaving.Attempt P A D)) : ℚ :=
  (attempts.map (attemptDelta region)).sum

